export function getIconForLanguageExtension({
  extension,
  name,
  className
}: {
  extension?: string;
  name?: string;
  className?: string;
}) {
  name = name?.toLocaleLowerCase();

  if (name?.includes("tailwind")) {
    return <LanguageIcons.tailwindcss className={cn("size-4", className)} />;
  }
  if (name?.startsWith("docker-compose.yml")) {
    return <LanguageIcons.docker className={cn("size-4", className)} />;
  }
  if (name?.startsWith("socket.io")) {
    return <LanguageIcons.socketio className={cn("size-4", className)} />;
  }
  if (name?.includes("motion")) {
    return <LanguageIcons.motion className={cn("size-4", className)} />;
  }
  if (name?.includes("nodejs")) {
    return <LanguageIcons.nodejs className={cn("size-4", className)} />;
  }
  if (name?.includes("nextjs")) {
    return <LanguageIcons.nextjs className={cn("size-4", className)} />;
  }
  if (name?.includes("typescript")) {
    return <LanguageIcons.ts className={cn("size-4", className)} />;
  }
  if (name?.includes("mongodb")) {
    return <LanguageIcons.mongodb className={cn("size-4", className)} />;
  }
  if (name?.includes("react")) {
    return <LanguageIcons.tsx className={cn("size-4", className)} />;
  }
  if (name?.includes("shadcn")) {
    return <LanguageIcons.shadcn className={cn("size-4", className)} />;
  }
  if (name?.includes("express")) {
    return <LanguageIcons.expressjs className={cn("size-4", className)} />;
  }
  if (name?.includes("html")) {
    return <LanguageIcons.html className={cn("size-4", className)} />;
  }
  if (name?.includes("css")) {
    return <LanguageIcons.css className={cn("size-4", className)} />;
  }
  if (name?.includes("javascript")) {
    return <LanguageIcons.js className={cn("size-4", className)} />;
  }
  if (name?.includes("tanstack")) {
    return <LanguageIcons.tanstack className={cn("size-4", className)} />;
  }
  if (name?.includes("mysql")) {
    return <LanguageIcons.mysql className={cn("size-4", className)} />;
  }
  if (name?.includes("postgres")) {
    return <LanguageIcons.pg className={cn("size-4", className)} />;
  }
  if (name?.includes("redis")) {
    return <LanguageIcons.redis className={cn("size-4", className)} />;
  }
  if (name?.includes("redux")) {
    return <LanguageIcons.redux className={cn("size-4", className)} />;
  }
  if (name?.includes("github")) {
    return <LanguageIcons.github className={cn("size-4", className)} />;
  }
  if (name?.includes("git")) {
    return <LanguageIcons.git className={cn("size-4", className)} />;
  }
  if (name?.includes("postman")) {
    return <LanguageIcons.postman className={cn("size-4", className)} />;
  }
  if (name?.includes("figma")) {
    return <LanguageIcons.figma className={cn("size-4", className)} />;
  }
  if (name?.includes("vscode")) {
    return <LanguageIcons.vscode className={cn("size-4", className)} />;
  }
  if (name?.includes("zod")) {
    return <LanguageIcons.zod className={cn("size-4", className)} />;
  }
  if (name?.includes("cursor")) {
    return <LanguageIcons.cursor className={cn("size-4", className)} />;
  }
  if (name?.includes("chatgpt")) {
    return <LanguageIcons.chatgpt className={cn("size-4", className)} />;
  }
  if (name?.includes("claude")) {
    return <LanguageIcons.claude className={cn("size-4", className)} />;
  }
  if (name?.includes("eslint")) {
    return <LanguageIcons.eslint className={cn("size-4", className)} />;
  }
  if (name?.includes("prettier")) {
    return <LanguageIcons.prettier className={cn("size-4", className)} />;
  }
  if (name?.includes("npm")) {
    return <LanguageIcons.npm className={cn("size-4", className)} />;
  }
  if (name?.includes("drizzle")) {
    return <LanguageIcons.drizzle className={cn("size-4", className)} />;
  }
  if (name?.includes("docker")) {
    return <LanguageIcons.docker className={cn("size-4", className)} />;
  }
  if (name?.includes("yml") || name?.includes("yaml")) {
    return <LanguageIcons.yml className={cn("size-4", className)} />;
  }

  switch (extension) {
    case "json":
      return <LanguageIcons.json className="size-4" />;
    case "cpp":
      return <LanguageIcons.cpp className="size-4" />;
    case "javascript":
    case "jsx":
      return <LanguageIcons.tsx className="size-4" />;
    case "js":
      return <LanguageIcons.js className="size-4" />;
    case "ts":
    case "typescript":
      return <LanguageIcons.ts className="fill-foreground size-4" />;
    case "bash":
      return <LanguageIcons.bash className="size-4" />;
    case "dotenv":
      return <LanguageIcons.env className="size-4" />;
    case "prisma":
      return <LanguageIcons.prisma className="size-4" />;
    case "sql":
      return <LanguageIcons.sql className="size-4" />;
    case "yml":
    case "yaml":
      return <LanguageIcons.yml className="size-4" />;

    case "mdx":
    case "md":
    case "markdown":
      return <LanguageIcons.mdx className="size-4" />;
    default:
      return <FileIcon className="size-4" />;
  }
}

export function getPackageManagerIcon(
  manager: PackageManager,
  className?: string
) {
  switch (manager) {
    case "npm":
      return <LanguageIcons.npm className={cn("size-4", className)} />;
    case "yarn":
      return <LanguageIcons.yarn className={cn("size-4", className)} />;
    case "pnpm":
      return <LanguageIcons.pnpm className={cn("size-4", className)} />;
    case "bun":
      return <LanguageIcons.bun className={cn("size-4", className)} />;
    default:
      return <LanguageIcons.bash className={cn("size-4", className)} />;
  }
}
